 29	static ssize_t _enc_domain_name(uint8_t *out, const char *domain_name)
 30	{
 31	    /*
 32	     * DNS encodes domain names with "<len><part><len><part>", e.g.,
 33	     * "example.org" ends up as "\7example\3org" in the packet.
 34	     */
 35	    uint8_t *part_start = out;
 36	    uint8_t *out_pos = ++out;
 37	
 38	    char c;
 39	
 40	    while ((c = *domain_name)) {
 41	        if (c == '.') {
 42	            /* replace dot with length of name part as byte */
 43	            *part_start = (out_pos - part_start - 1);
 44	            part_start = out_pos++;
 45	        }
 46	        else {
 47	            *out_pos++ = c;
 48	        }
 49	        domain_name++;
 50	    }
 51	
 52	    *part_start = (out_pos - part_start - 1);
 53	    *out_pos++ = 0;
 54	
 55	    return out_pos - out + 1;
 56	}
