 58	static unsigned _put_short(uint8_t *out, uint16_t val)
 59	{
 60	    memcpy(out, &val, 2);
 61	    return 2;
 62	}
 63	
 64	static unsigned _get_short(const uint8_t *buf)
 65	{
 66	    uint16_t _tmp;
 67	    memcpy(&_tmp, buf, 2);
 68	    return _tmp;
 69	}
