 71	static ssize_t _skip_hostname(const uint8_t *buf, size_t len,
 72	                              const uint8_t *bufpos)
 73	{
 74	    const uint8_t *buflim = buf + len;
 75	    unsigned res = 0;
 76	
 77	    if (bufpos >= buflim) {
 78	        /* out-of-bound */
 79	        return -EBADMSG;
 80	    }
 81	    /* handle DNS Message Compression */
 82	    if (*bufpos >= 192) {
 83	        if ((bufpos + 2) >= buflim) {
 84	            return -EBADMSG;
 85	        }
 86	        return 2;
 87	    }
 88	
 89	    while (bufpos[res]) {
 90	        res += bufpos[res] + 1;
 91	        if ((&bufpos[res]) >= buflim) {
 92	            /* out-of-bound */
 93	            return -EBADMSG;
 94	        }
 95	    }
 96	    return res + 1;
 97	}
