 99	size_t dns_msg_compose_query(void *dns_buf, const char *domain_name,
100	                             uint16_t id, int family)
101	{
102	    uint8_t *buf = dns_buf;
103	
104	    dns_hdr_t *hdr = (dns_hdr_t*) buf;
105	    memset(hdr, 0, sizeof(*hdr));
106	    hdr->id = htons(id);
107	    hdr->flags = htons(0x0120);
108	    hdr->qdcount = htons(1 + (family == AF_UNSPEC));
109	
110	    uint8_t *bufpos = buf + sizeof(*hdr);
111	
112	    unsigned _name_ptr;
113	    if ((family == AF_INET6) || (family == AF_UNSPEC)) {
114	        _name_ptr = (bufpos - buf);
115	        bufpos += _enc_domain_name(bufpos, domain_name);
116	        bufpos += _put_short(bufpos, htons(DNS_TYPE_AAAA));
117	        bufpos += _put_short(bufpos, htons(DNS_CLASS_IN));
118	    }
119	
120	    if ((family == AF_INET) || (family == AF_UNSPEC)) {
121	        if (family == AF_UNSPEC) {
122	            bufpos += _put_short(bufpos, htons((0xc000) | (_name_ptr)));
123	        }
124	        else {
125	            bufpos += _enc_domain_name(bufpos, domain_name);
126	        }
127	        bufpos += _put_short(bufpos, htons(DNS_TYPE_A));
128	        bufpos += _put_short(bufpos, htons(DNS_CLASS_IN));
129	    }
130	    return bufpos - buf;
131	}
132	
133	int dns_msg_parse_reply(const uint8_t *buf, size_t len, int family,
134	                        void *addr_out, uint32_t *ttl)
135	{
136	    const uint8_t *buflim = buf + len;
137	    const dns_hdr_t *hdr = (dns_hdr_t *)buf;
138	    const uint8_t *bufpos = buf + sizeof(*hdr);
139	
140	    /* skip all queries that are part of the reply */
141	    for (unsigned n = 0; n < ntohs(hdr->qdcount); n++) {
142	        ssize_t tmp = _skip_hostname(buf, len, bufpos);
143	        if (tmp < 0) {
144	            return tmp;
145	        }
146	        bufpos += tmp;
147	        /* skip type and class of query */
148	        bufpos += (RR_TYPE_LENGTH + RR_CLASS_LENGTH);
149	    }
150	
151	    for (unsigned n = 0; n < ntohs(hdr->ancount); n++) {
152	        ssize_t tmp = _skip_hostname(buf, len, bufpos);
153	        if (tmp < 0) {
154	            return tmp;
155	        }
156	        bufpos += tmp;
157	        if ((bufpos + RR_TYPE_LENGTH + RR_CLASS_LENGTH +
158	             RR_TTL_LENGTH + sizeof(uint16_t)) >= buflim) {
159	            return -EBADMSG;
160	        }
161	        uint16_t _type = ntohs(_get_short(bufpos));
162	        bufpos += RR_TYPE_LENGTH;
163	        uint16_t class = ntohs(_get_short(bufpos));
164	        bufpos += RR_CLASS_LENGTH;
165	        if (ttl) {
166	            *ttl = byteorder_bebuftohl(bufpos);
167	        }
168	        bufpos += RR_TTL_LENGTH;
169	
170	        unsigned addrlen = ntohs(_get_short(bufpos));
171	        /* skip unwanted answers */
172	        if ((class != DNS_CLASS_IN) ||
173	                ((_type == DNS_TYPE_A) && (family == AF_INET6)) ||
174	                ((_type == DNS_TYPE_AAAA) && (family == AF_INET)) ||
175	                ! ((_type == DNS_TYPE_A) || ((_type == DNS_TYPE_AAAA))
176	                    )) {
177	            if (addrlen > len) {
178	                /* buffer wraps around memory space */
179	                return -EBADMSG;
180	            }
181	            bufpos += addrlen;
182	            /* other out-of-bound is checked in `_skip_hostname()` at start of
183	             * loop */
184	            continue;
185	        }
186	        if (((addrlen != INADDRSZ) && (family == AF_INET)) ||
187	            ((addrlen != IN6ADDRSZ) && (family == AF_INET6)) ||
188	            ((addrlen != IN6ADDRSZ) && (addrlen != INADDRSZ) &&
189	             (family == AF_UNSPEC))) {
190	            return -EBADMSG;
191	        }
192	        bufpos += RR_RDLENGTH_LENGTH;
193	        if ((bufpos + addrlen) > buflim) {
194	            return -EBADMSG;
195	        }
196	
197	        memcpy(addr_out, bufpos, addrlen);
198	        return addrlen;
199	    }
200	
201	    return -EBADMSG;
202	}
